@media(max-width:620px){.xd5-page .xd305-content-page{padding:28px 0 48px}.xd305-content-page>.xd-container{width:calc(100% - 30px)}.xd305-content-page .xd-detail-body{padding:28px 20px}.xd305-content-page .xd-detail-body h1{font-size:30px}.xd305-content-page .xd-detail-summary{font-size:15px}.xd305-content-page .xd-rich-content h2{font-size:21px}.xd305-content-grid{grid-template-columns:minmax(0,1fr)}.xd305-content-collection{margin-top:32px}.xd305-content-collection>h2{font-size:25px}}
